const AlternativeAbilityTrial = (() => {
  const ranks = ['D', 'C', 'C+', 'B', 'A', 'AA', 'S', 'SS'];
  const scores = [66, 71, 73.5, 76, 81, 83, 86, 91];
  const MS_PER_DAY = 86400000;
  function dayOf(date) {
    return Date.UTC(Math.floor(date / 10000), Math.floor(date / 100) % 100 - 1, date % 100) / MS_PER_DAY;
  }
  const turfDistanceWindows = new Map([[2000, [1800, 2400]], [2400, [2000, 3000]], [3000, [2400, 3360]]]);
  function isNearDistance(surface, distance, priorDistance) {
    const window = surface === 0 ? turfDistanceWindows.get(distance) : null;
    if (window) return window[0] <= priorDistance && priorDistance <= window[1];
    return Math.abs(priorDistance - distance) <= Math.max(200, distance * 0.12);
  }
  function normalizeGoing(going) {
    return going === '稍' ? '稍重' : going === '不' ? '不良' : going;
  }
  function features(records, context) {
    const start = records.findIndex(row => row[0] >= context.date);
    const end = start < 0 ? records.length : start;
    const recent = records.slice(Math.max(0, end - 7), end)
      .filter(row => row[2] === context.surface && Number.isFinite(row[7]));
    if (!recent.length) return null;
    const last = recent.at(-1);
    const delta = Math.abs(last[3] - context.distance);
    const near = recent.filter(row => isNearDistance(context.surface, context.distance, row[3]));
    const course = near.filter(row => row[1] === context.venue);
    const exact = course.filter(row => row[3] === context.distance);
    const sameClass = recent.filter(row => row[4] === context.cls && row[3] === context.distance && row[9] === context.cohort && Number.isFinite(row[6]));
    const best = rows => rows.length ? Math.max(...rows.map(row => row[7])) : null;
    const near9 = best(near), course9 = best(course), exact9 = best(exact);
    const recent3 = recent.slice(-3);
    const x = [context.cls, context.surface, context.cohort, context.age, last[7], sameClass.at(-1)?.[6] ?? null,
      dayOf(context.date) - dayOf(last[0]), delta, last[9], last[5], last[4], near9, course9, exact9,
      near.length, exact.length, Number(context.going === normalizeGoing(last[8])), recent.length,
      Math.round(recent3.reduce((sum, row) => sum + row[7], 0) / recent3.length * 1e6) / 1e6];
    const peak = best(recent);
    const peakRow = recent.findLast(row => row[7] === peak);
    return {x, n: recent.length, last9: last[7], near9, relative: sameClass.at(-1)?.[6] ?? null, peak,
      peakAge: dayOf(context.date) - dayOf(peakRow[0]), values: recent.map(row => row[7]),
      bestUsed: Math.max(last[7], near9 ?? -Infinity, course9 ?? -Infinity, exact9 ?? -Infinity, best(recent3))};
  }
  function predict(model, x) {
    const logits = model.baseline.slice();
    for (const group of model.trees) {
      group.forEach((tree, klass) => {
        let node = tree[0];
        while (node.length > 1) {
          const [feature, threshold, left, right, missingLeft] = node;
          const value = x[feature];
          const goesLeft = Number.isFinite(value) ? value <= threshold : missingLeft;
          node = tree[goesLeft ? left : right];
        }
        logits[klass] += node[0];
      });
    }
    const max = Math.max(...logits);
    const exp = logits.map(value => Math.exp(value - max));
    const total = exp.reduce((sum, value) => sum + value, 0);
    const probability = exp.map(value => value / total);
    const costs = model.costs.map(row => row.reduce((sum, value, i) => sum + value * probability[i], 0));
    return {probability, rank: costs.indexOf(Math.min(...costs))};
  }
  function reserve(values, last, bestUsed, age) {
    const [best, second] = [...values].sort((a, b) => b - a);
    const gap = best - Math.max(last, bestUsed);
    if (age > 180 || !(gap >= 3) || !(second >= best - 5)) return 0;
    return Math.min(0.8, gap * 0.16);
  }
  function profile(model, records, context, h7) {
    const unavailable = (basis, neutral = true) => ({
      rank: neutral ? 'C+' : '', raw: neutral ? 73.5 : null, basis, h7UpsidePoints: 0,
      confidence: neutral ? '暫定' : '対象外', evidence: null
    });
    if (context.cls === 1 || ![0, 1].includes(context.surface)) return unavailable('新馬・障害は試算対象外', false);
    if (!Number.isInteger(context.cls) || !(context.distance > 0)) return unavailable('クラスまたは距離未確認');
    const row = features(records, context);
    if (!row) return unavailable('同じ芝・ダートの有効な補9なし');
    const modelResult = predict(model, row.x);
    const rank = modelResult.rank;
    const h7Compatible = Number.isFinite(h7) && h7 === row.peak;
    // Only compare input H7 numerically when it matches the same-scale
    // reconstructed peak. Unmatched H7 may be a relative TARGET index.
    const bump = reserve(row.values, row.last9, row.bestUsed, row.peakAge);
    const existingRanks = [0, 1, 3, 4, 5, 6, 7];
    const support = modelResult.probability.reduce((sum, p, i) => sum + (Math.abs(rank - existingRanks[i]) <= 1 ? p : 0), 0);
    const confidence = row.n < 2 || !context.cohort ? '参考' : support >= .9 ? '高' : '参考';
    const h7Note = (h7Compatible ? '入力H7照合済' : Number.isFinite(h7) ? '入力H7尺度一致未確認' : '入力H7なし') + (bump ? '／補9の近7走最高値から余力' : '／余力加点なし');
    const basis = `直近補9 ${row.last9}／近距離上位 ${row.near9 ?? '－'}／同級同距離補正 ${row.relative ?? '－'}／参照${row.n}走／${h7Note}`;
    return {rank: ranks[rank], raw: scores[rank] + bump, basis, h7UpsidePoints: bump, confidence, evidence: row};
  }
  return {dayOf, features, predict, profile, reserve, isNearDistance};
})();
if (typeof module !== 'undefined') module.exports = AlternativeAbilityTrial;

const AlternativeAbilityEncoded = ["",""];
